function setupGameCardModals(){const t={"Cyber Nexus":{category:"Action",rating:"4.8",players:"2.3K",image:"/api/placeholder/900/600",description:"Enter the world of Cyber Nexus, a high-octane action game where you battle in a dystopian future. Master your cybernetic enhancements and battle against rival factions in stunning environments.",features:["Immersive Open World","Character Customization","Multiplayer Arenas","Story Campaign","Weekly Challenges","Customizable Weapons"]},"Galactic Command":{category:"Strategy",rating:"4.6",players:"1.8K",image:"/api/placeholder/900/600",description:"Command your fleet across the galaxy in this epic space strategy game. Build alliances, manage resources, and engage in tactical battles to expand your cosmic empire and protect your territory from rival factions.",features:["Real-time Strategy","Fleet Customization","Resource Management","Diplomacy System","PvP Battles","Alliance Gameplay"]},"Eternal Realms":{category:"RPG",rating:"4.9",players:"3.1K",image:"/api/placeholder/900/600",description:"Embark on an epic journey through magical lands filled with mystical creatures and ancient powers. Create your unique character, master various skills, and uncover the secrets of the Eternal Realms.",features:["Open World Exploration","Character Progression","Epic Quests","Crafting System","Guild Mechanics","PvE & PvP Content"]},"Tactical Ops":{category:"Shooter",rating:"4.7",players:"2.9K",image:"/api/placeholder/900/600",description:"Join elite special forces in high-stakes tactical operations around the world. Master weapons, coordinate with your team, and complete objectives in this intense first-person shooter experience.",features:["Team-based Gameplay","Realistic Weapons","Multiple Game Modes","Seasonal Rankings","Custom Loadouts","Strategic Maps"]},"Snake Game":{category:"Arcade",rating:"4.2",players:"5.0K",image:"/public/images/snakeGame.jpg",description:"Classic Snake Game with smooth controls and challenging levels. Guide your snake to eat food and grow longer without crashing into the walls or yourself. Perfect for quick fun and improving reflexes.",features:["Classic Gameplay","Multiple Levels","Simple Controls","High Score Tracking","Mobile Friendly","Retro Graphics"],Url:"/pages/Games/snakeGame.html"},"Slide Number Game":{category:"Puzzle",rating:"4.5",players:"3.2K",image:"/public/images/slideNumberGame.jpg",description:"Engage your brain with the classic Slide Number Puzzle. Slide the numbered tiles to arrange them in numerical order, testing your problem-solving skills and patience. A perfect mix of challenge and fun for all ages.",features:["Classic Puzzle Gameplay","Multiple Difficulty Levels","Smooth Sliding Animations","Timer and Moves Tracking","Mobile Friendly","Clean and Minimalist Design"],Url:"/pages/Games/slideNumberGame.html"},"Image Matching":{category:"Puzzle",rating:"4.3",players:"4.5K",image:"/public/images/imageMatching.jpg",description:"Test your memory and concentration with the Image Matching game. Flip cards to find pairs of matching images. Fun and addictive gameplay suitable for players of all ages.",features:["Classic Memory Match Gameplay","Variety of Image Themes","Time Challenge Mode","Simple and Intuitive Controls","Mobile Friendly","Colorful Graphics"],Url:"/pages/Games/imageMatching.html"},"Color Puzzle":{category:"Puzzle",rating:"4.6",players:"3.8K",image:"/public/images/colorPuzzle.jpg",description:"Train your brain with the Color Puzzle game. Arrange and match colors by solving fun and challenging puzzles. A great way to improve logical thinking and color recognition.",features:["Unique Color Matching Mechanics","Multiple Challenging Levels","Smooth and Responsive Controls","Progress Tracking","Mobile Friendly","Bright and Engaging Visuals"],Url:"/pages/Games/colorPuzzle.html"}};let e=document.querySelector(".game-modal-container");if(!e){e=document.createElement("div");e.className="game-modal-container";document.body.appendChild(e);const t=document.createElement("div");t.className="close-modal";t.innerHTML='<i class="fas fa-times"></i>';e.appendChild(t);t.addEventListener("click",()=>closeGameModal(e));document.addEventListener("keydown",function(t){if(t.key==="Escape")closeGameModal(e)});e.addEventListener("click",function(t){if(t.target===e)closeGameModal(e)})}const n=document.querySelectorAll(".game-card");n.forEach(n=>{n.addEventListener("click",function(o){if(o.target.classList.contains("play-now"))return;const a=n.querySelector("h3").textContent;const i=t[a];if(!i){console.error(`Game data not found for: ${a}`);return}const l=`
          <div class="game-modal">
            <div class="game-modal-image">
              <img src="${i.image}" alt="${a}">
              <span class="game-category">${i.category}</span>
            </div>
            <div class="game-modal-content">
              <h2>${a}</h2>
              <div class="game-meta-expanded">
                <span><i class="fas fa-star"></i> ${i.rating}</span>
                <span><i class="fas fa-users"></i> ${i.players} Active</span>
              </div>
              <p class="game-description">${i.description}</p>
              <div class="game-features">
                <h3>Key Features</h3>
                <div class="feature-list">
                  ${i.features.map(t=>`<span class="feature-item">${t}</span>`).join("")}
                </div>
              </div>
              <div class="game-modal-buttons">
                <button class="play-now-expanded" onclick="startGame('${i.Url||"#"}')">Start Game</button>
              </div>
            </div>
          </div>
        `;e.innerHTML="";e.insertAdjacentHTML("beforeend",l);const s=document.createElement("div");s.className="close-modal";s.innerHTML='<i class="fas fa-times"></i>';e.appendChild(s);s.addEventListener("click",()=>closeGameModal(e));requestAnimationFrame(()=>{e.classList.add("active");setTimeout(()=>{const t=document.querySelector(".game-modal");if(t){t.classList.add("active")}},100)})})})}
function closeGameModal(t){const e=document.querySelector(".game-modal");if(e){e.classList.remove("active");setTimeout(()=>{t.classList.remove("active")},300)}}
function startGame(t){if(t){window.location.href=t}else{console.error("Game URL not found")}}
function setupTournamentModals(){const t=document.querySelectorAll(".tournament-btn");const e=document.querySelector(".tournament-modal-backdrop");if(!e){console.error("Tournament modal backdrop not found");return}const n=e.querySelector(".tournament-modal-close");const o=e.querySelector(".tournament-register-btn");t.forEach(t=>{t.addEventListener("click",function(t){t.preventDefault();openTournamentModal(e)})});if(n){n.addEventListener("click",()=>closeTournamentModal(e))}e.addEventListener("click",function(t){if(t.target===e){closeTournamentModal(e)}});if(o){o.addEventListener("click",function(){window.location.href="register.html"})}}
function openTournamentModal(t){t.classList.add("active");document.body.style.overflow="hidden"}
function closeTournamentModal(t){t.classList.remove("active");document.body.style.overflow=""}
document.addEventListener("DOMContentLoaded",function(){setupGameCardModals();setupTournamentModals()});
